const b = $json.body;
const invalid = (error, status = 400, code = 'INVALID_INPUT') => [{json:{valid:false,error,status,code}}];
const uuid = /^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i;
if (!b || typeof b !== 'object' || Array.isArray(b)) return invalid('Передайте JSON-объект.');
const validId = value => typeof value === 'string' && uuid.test(value);
if (!validId(b.event_id)) return invalid('event_id — UUID, который ваш сервер сохранил для этой операции.');
if (typeof b.phone !== 'string' || !/^\+[1-9][0-9]{7,14}$/.test(b.phone)) return invalid('Укажите телефон в формате E.164, например +77071234567.');
const connectionId = $json.waix_connection_id;
const templateName = $json.waix_template;
const language = $json.waix_language;
if (!validId(connectionId) || typeof templateName !== 'string' || templateName === 'your_approved_template' || !/^[a-z0-9_]{1,512}$/.test(templateName) || typeof language !== 'string' || !/^[a-z]{2,3}(?:_[A-Z]{2})?$/.test(language)) return invalid('Укажите Connection ID, одобренный шаблон и язык в узле WAIX settings.', 500, 'WORKFLOW_NOT_CONFIGURED');
if (b.whatsapp_consent !== true) return invalid('Нужно подтверждённое согласие клиента на сообщения WhatsApp.');
if (typeof b.name !== 'string' || !b.name.trim() || b.name.length > 500) return invalid('Заполните name: строка до 500 символов.');
return [{json:{valid:true,idempotency_key:b.event_id,body:{connection_id:connectionId,to:b.phone,type:'template',template:{name:templateName,language:{code:language},components:[{type:'body',parameters:[{type:'text',text:b.name.trim()}]}]}}}}];

// HTTP Request возвращает текст: даже HTML от прокси станет понятной HTTP-ошибкой.
const status = Number($json.statusCode);
const headers = $json.headers || {};
const requestId = headers['x-request-id'] || headers['X-Request-Id'];
const retryAfter = headers['retry-after'] || headers['Retry-After'];
const meta = { request_id: typeof requestId === 'string' ? requestId : null };
let body = $json.body;
try { if (typeof body === 'string') body = JSON.parse(body); } catch { body = null; }
const object = body && typeof body === 'object' && !Array.isArray(body);
let responseCode = Number.isInteger(status) && status >= 400 && status <= 599 ? status : 502;
if (status >= 200 && status < 300 && object) responseCode = status;
if (!object) body = {error: 'WAIX вернул ответ, который не удалось прочитать.', code: 'INVALID_RESPONSE', ...meta};
if (status >= 300 && status < 400) body = {error: 'WAIX вернул перенаправление. Проверьте адрес API.', code: 'REDIRECT_DISALLOWED', ...meta};
if (body.data && typeof body.data === 'object' && !Array.isArray(body.data)) {
  const {test_code, ...safe} = body.data;
  body = {...body, data: safe};
}
const responseHeaders = [{name: 'Cache-Control', value: 'no-store'}];
if (typeof requestId === 'string' && /^[A-Za-z0-9_.:-]{1,160}$/.test(requestId)) responseHeaders.push({name:'X-Request-Id',value:requestId});
if (typeof retryAfter === 'string' && (/^[0-9]{1,8}$/.test(retryAfter) || /^[A-Za-z]{3}, [0-9]{2} [A-Za-z]{3} [0-9]{4} [0-9:]{8} GMT$/.test(retryAfter))) responseHeaders.push({name:'Retry-After',value:retryAfter});
return [{json:{body,responseCode,responseHeaders}}];
